Create unit `tasks` and implement `add_all`: add d to every element of `a`, for d and every element in [-1000, 1000] (you may also assume a.len() <= 1000000, as `u9::d108` does). The contract must state that each element equals its old value plus d.

Required signature (in unit `tasks`):
fn add_all(a: &mut [i64], d: i64) -> ()

reference.code:
spec fn small_d(d: i64) -> bool { -1000 <= d && d <= 1000 }

spec fn added_below(a: &[i64], b: &[i64], d: i64, n: usize) -> bool {
    a.len() == b.len() && (forall|k: usize| k < a.len() ==> ((k < n ==> #[trigger] a[k] == b[k] + d) && (k >= n ==> a[k] == b[k])))
}

spec fn added(a: &[i64], b: &[i64], d: i64) -> bool { a.len() == b.len() && (forall|k: usize| k < a.len() ==> #[trigger] a[k] == b[k] + d) }

#[effects(pure)]
#[uses(u9::d108, small_d, added_below, added)]
fn add_all(a: &mut [i64], d: i64) -> ()
    requires u9::d108(a), small_d(d),
    ensures added(a, old(a), d),
{
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), u9::d108(old(a)), added_below(a, old(a), d, k),
        decreases a.len() - k,
    {
        a[k] = a[k] + d;
        k = k + 1;
    }
}

